using System;using System.Collections.Generic;using RimWorld;using UnityEngine;using Verse;
namespace ElementalHearts {
 public static class AuroraVfx {
  public static readonly string[] Names={"RimefallCrescent","AuroraBlitzWake","AuroraBlitzFlash","AuroraBlitzSlash","FrostcrownWaltz","AuroraCurtainFormation","AuroraCurtainLoop","AuroraCurtainRelease","AuroraCataclysm","FrostStreak","FreezeShell","MirrorfrostMirage","MirrorfrostRetreat","MirrorfrostCounter","ThroneTelegraph","ThroneFormation","ThroneShatter","RimeStep","TravelDeparture","TravelArrival","Coronation","Halo","BackAura","SnowDrift","SwordClash"};
  static readonly Material[,] frames=new Material[25,16],bodies=new Material[8,3];static readonly string[] bodyNames={"Male","Female","Thin","Fat","Hulk","Child","Baby","FemaleBB"};
  public static int Count(int n){return n==16?16:n==9?4:n==10||n==21||n==22||n==23?6:8;}
  public static Material Frame(int n,int f){f=Mathf.Clamp(f,0,Count(n)-1);return frames[n,f]??(frames[n,f]=MaterialPool.MatFrom("Effects/ElementalHearts/AuroraIncarnate/Frames/"+Names[n]+"_"+f.ToString("00"),ShaderDatabase.Transparent));}
  public static Material Body(Pawn p){if(CourtAppearance.WearingKit(p))return CourtAppearance.Body(p);int b=Array.IndexOf(bodyNames,p.story==null||p.story.bodyType==null?"Male":p.story.bodyType.defName);if(b<0)b=0;int d=p.Rotation==Rot4.South?0:p.Rotation==Rot4.North?2:1;return bodies[b,d]??(bodies[b,d]=MaterialPool.MatFrom("Things/Pawn/Humanlike/Apparel/AuroraIncarnateRegalia/AuroraIncarnateRegalia_"+bodyNames[b]+"_"+new[]{"south","east","north"}[d],ShaderDatabase.Transparent));}
  static MapComponent_AuroraVfx Controller(Pawn p,Vector3 a,Vector3 b){return p!=null&&p.Spawned&&StormBlitzFx.Visible(p.Map,a,b)?p.Map.GetComponent<MapComponent_AuroraVfx>():null;}
  public static void Track(Pawn p){if(p!=null&&p.Spawned)p.Map.GetComponent<MapComponent_AuroraVfx>().Track(p);}
  public static int Owned(Pawn p,int sprite,Vector3 at,float width,float height,int duration,int elapsed){if(p==null||!p.Spawned)return 0;return p.Map.GetComponent<MapComponent_AuroraVfx>().Add(sprite,at,at,width,height,Math.Max(1,duration-elapsed),0,false,Mathf.Clamp01(elapsed/(float)duration),p);}
  public static void Burst(Pawn p,int sprite,Vector3 at,float size,int duration){var c=Controller(p,at,at);if(c!=null)c.Add(sprite,at,at,size,size,duration,0,false);}
  public static void Wave(Pawn p,int sprite,Vector3 a,Vector3 b,int duration,float size){var c=Controller(p,a,b);if(c!=null)c.Add(sprite,a,b,size,size,duration,(b-a).AngleFlat()-90,true);}
  public static void Line(Pawn p,int sprite,Vector3 a,Vector3 b,int duration,float width){var c=Controller(p,a,b);if(c!=null&&(a-b).sqrMagnitude>.01f)c.Add(sprite,(a+b)*.5f,(a+b)*.5f,Math.Max(.8f,(b-a).magnitude+.5f),width,duration,(b-a).AngleFlat()-90,false);}
  public static void Echo(Pawn p,Vector3 at){if(!ElementalHeartsMod.Settings.showAfterimages)return;var c=Controller(p,at,at);if(c!=null)c.Echo(p,at);}
  public static void Step(Pawn p,Map map,Vector3 a,Vector3 b){var c=map.GetComponent<MapComponent_AuroraVfx>();if(StormBlitzFx.Visible(map,a,a))c.Add(17,a,a,3,3,22,0,false);if(StormBlitzFx.Visible(map,b,b))c.Add(17,b,b,3.5f,3.5f,24,0,false);ElementalAudio.Ability(p,ElementalSound.Dash);}
 }
 public sealed class MapComponent_AuroraVfx:MapComponent {
  struct Effect{public bool active,wave;public int id,sprite,tick,duration;public Vector3 a,b;public float width,height,angle,animationStart;public Pawn owner;public Verse.AI.Job job;}
  struct Ghost{public bool active,west;public int tick;public Vector3 at;public float size;public Material body;}
  readonly Effect[] effects=new Effect[192];readonly Ghost[] ghosts=new Ghost[64];readonly List<Pawn> tracked=new List<Pawn>();int cursor,ghostCursor,nextId;MaterialPropertyBlock block;
  public MapComponent_AuroraVfx(Map map):base(map){}
  public void Track(Pawn p){if(p!=null&&tracked.Count<256&&!tracked.Contains(p))tracked.Add(p);}
  public override void FinalizeInit(){foreach(var p in map.mapPawns.AllPawnsSpawned)if(AuroraIncarnate.Active(p)||p.CurJobDef!=null&&p.CurJobDef.defName==AuroraIncarnate.Ritual)Track(p);}
  public int Add(int sprite,Vector3 a,Vector3 b,float width,float height,int duration,float angle,bool wave,float animationStart=0,Pawn owner=null){if(++nextId<=0)nextId=1;effects[cursor]=new Effect{active=true,id=nextId,sprite=sprite,a=a,b=b,width=width,height=height,tick=Find.TickManager.TicksGame,duration=Math.Max(1,duration),angle=angle,wave=wave,animationStart=animationStart,owner=owner,job=owner==null?null:owner.CurJob};cursor=(cursor+1)%effects.Length;return nextId;}
  public void Stop(int id){if(id<=0)return;for(int i=0;i<effects.Length;i++)if(effects[i].active&&effects[i].id==id){effects[i].active=false;return;}}
  public void Echo(Pawn p,Vector3 at){ghosts[ghostCursor]=new Ghost{active=true,west=p.Rotation==Rot4.West,tick=Find.TickManager.TicksGame,at=at,size=HumanlikeMeshPoolUtility.HumanlikeBodyWidthForPawn(p),body=AuroraVfx.Body(p)};ghostCursor=(ghostCursor+1)%ghosts.Length;}
  public override void MapComponentTick(){int now=Find.TickManager.TicksGame;if(now%15!=0)return;tracked.RemoveAll(p=>p==null||p.Destroyed||!p.Spawned||p.Map!=map||!AuroraIncarnate.Active(p)&&(p.CurJobDef==null||p.CurJobDef.defName!=AuroraIncarnate.Ritual));for(int i=0;i<effects.Length;i++)if(effects[i].active&&(now-effects[i].tick>=effects[i].duration||effects[i].owner!=null&&effects[i].owner.CurJob!=effects[i].job))effects[i].active=false;}
  void Draw(int n,int f,Vector3 at,float width,float height,float angle,float alpha,Color tint,bool behind=false){var cell=at.ToIntVec3();if(!cell.InBounds(map)||cell.Fogged(map)||alpha<.001f)return;at.y=behind?AltitudeLayer.MoteLow.AltitudeFor():AltitudeLayer.MoteOverhead.AltitudeFor();tint.a=alpha*ElementalHeartsMod.Settings.effectOpacity;block.SetColor(ShaderPropertyIDs.Color,tint);Graphics.DrawMesh(MeshPool.plane10,Matrix4x4.TRS(at,Quaternion.AngleAxis(angle,Vector3.up),new Vector3(width,1,height)),AuroraVfx.Frame(n,f),0,null,0,block);}
  void Sequence(int n,float phase,Vector3 at,float w,float h,float angle,float alpha,bool behind=false){int count=AuroraVfx.Count(n);int frame=Math.Min(count-1,(int)phase);float blend=phase-frame;Draw(n,frame,at,w,h,angle,alpha*(1-blend),Color.white,behind);if(frame<count-1||n==6||n==10||n>=21&&n<=23)Draw(n,(frame+1)%count,at,w,h,angle,alpha*blend,Color.white,behind);}
  public override void MapComponentDraw(){
   if(map!=Find.CurrentMap||Find.CameraDriver==null||ElementalHeartsMod.Settings.effectOpacity<=0)return;if(block==null)block=new MaterialPropertyBlock();int now=Find.TickManager.TicksGame;var view=Find.CameraDriver.CurrentViewRect.ExpandedBy(20);
   for(int i=0;i<effects.Length;i++){var e=effects[i];if(!e.active)continue;float elapsed=(now-e.tick)/(float)e.duration;if(elapsed>=1||e.owner!=null&&(!e.owner.Spawned||e.owner.Dead||e.owner.CurJob!=e.job)){effects[i].active=false;continue;}float t=Mathf.Lerp(e.animationStart,1,elapsed);var at=e.wave?Vector3.Lerp(e.a,e.b,t):(e.a+e.b)*.5f;if(!view.Contains(at.ToIntVec3()))continue;bool curtain=e.sprite==5||e.sprite==6||e.sprite==7||e.sprite==15||e.sprite==16||e.sprite==18||e.sprite==19;if(curtain)at.z+=e.height*.27f;int count=AuroraVfx.Count(e.sprite);float phase=e.sprite==6?((now-e.tick)/5f)%count:t*(count-1);Sequence(e.sprite,phase,at,e.width,e.height,e.angle,Mathf.Min(1,(1-t)*5)*(curtain?.68f:.9f),curtain||e.sprite==23||e.sprite==14);}
   for(int i=0;i<ghosts.Length;i++){var g=ghosts[i];if(!g.active)continue;float t=(now-g.tick)/16f;if(t>=1){ghosts[i].active=false;continue;}if(!view.Contains(g.at.ToIntVec3()))continue;float alpha=.35f*(1-t)*(1-t);block.SetColor(ShaderPropertyIDs.Color,new Color(.7f,1,1,alpha*ElementalHeartsMod.Settings.effectOpacity));var at=g.at;at.y=AltitudeLayer.MoteOverhead.AltitudeFor();Graphics.DrawMesh(MeshPool.plane10,Matrix4x4.TRS(at,Quaternion.identity,new Vector3(g.west?-g.size:g.size,1,g.size)),g.body,0,null,0,block);}
   int visible=0;foreach(var p in tracked){if(!p.Spawned||p.Dead||p.Downed||!view.Contains(p.Position)||p.Position.Fogged(map)||visible++>=64)continue;var ritual=p.jobs.curDriver as JobDriver_TranscendAurora;if(ritual!=null){float t=ritual.Progress;var at=p.Position.ToVector3Shifted();Sequence(20,t*7,at,Mathf.Lerp(5,12,t),Mathf.Lerp(5,12,t),0,.55f,true);continue;}if(!ElementalHeartsMod.Settings.showAura||!p.Drafted||!p.Awake()||!HediffComp_ElementalTransform.Active(p)||HediffComp_ElementalTransform.Transforming(p))continue;float life=Mathf.Clamp(Mathf.Sqrt(p.ageTracker.CurLifeStage.bodySizeFactor),.55f,1.25f);float phase=((now+p.thingIDNumber)/9f)%6;var pos=p.DrawPos;pos.z+=.3f*life;Sequence(22,phase,pos,2.6f*life,3*life,0,.23f,true);Sequence(23,((now+p.thingIDNumber)/10f)%6,p.Position.ToVector3Shifted(),2.3f*life,2.3f*life,0,.18f,true);var head=p.DrawPos+p.Drawer.renderer.BaseHeadOffsetAt(p.Rotation);head.z+=(.43f+.016f*Mathf.Sin(now*.05f))*life;Sequence(21,phase,head,1.12f*life,1.12f*life,0,.8f);}
  }
 }
 public static class AuroraUtility {
  public const string Depart="EH_AuroraTravelDepart",Arrive="EH_AuroraTravelArrive";
  public static int Emit(Pawn p,CelestialEffect effect,int duration,float width,float height,int elapsed){if(p==null||!p.Spawned)return 0;int sprite=effect==CelestialEffect.DepartureBeam?18:effect==CelestialEffect.ArrivalBeam?19:effect==CelestialEffect.TravelMotes?23:20;return p.Map.GetComponent<MapComponent_AuroraVfx>().Add(sprite,p.Position.ToVector3Shifted(),p.Position.ToVector3Shifted(),width,height,Math.Max(1,duration-elapsed),0,false,Mathf.Clamp01(elapsed/(float)duration),p);}
 }
}
